    """
    # Initialize the counters for each possible aisle position
    counters = {}
    for k in range(K):
        counters[f'H{k}'] = 0
    for l in range(L):
        counters[f'V{l}'] = 0

    # Count the number of chatting pairs that can be separated by each aisle
    for pair in chatting_pairs:
        for k, pos in enumerate(pair[:2]):
            for l, pos2 in enumerate(pair[2::]):
