def preorder_traversal(inorder, postorder):
    inorder_idx = {c: i for i, c in enumerate(inorder)}
    postorder_idx = {c: i for i, c in enumerate(postorder)}
    n = len(inorder)
    graph = {i: [] for i in range(n)}
    for i in range(n - 1):
        graph[postorder_idx[inorder[i]]].append(i)
    def build_tree(i):
        if i == n - 1:
            return [inorder[i]]
        left = build_tree(graph[i])
        right = build_tree(i + 1)
        return [inorder[i]] + left + right
    return ''.join(build_tree(0))

